define(['qtype_structuredsteps/widgets/plain'], function(PlainWidget) {
    function MathFieldWidget(fieldEl) {
        PlainWidget.call(this, fieldEl);
        this.inputHandler = null;
    }

    MathFieldWidget.prototype = Object.create(PlainWidget.prototype);
    MathFieldWidget.prototype.constructor = MathFieldWidget;

    MathFieldWidget.prototype.init = function() {
        var field = this.fieldEl;
        field.setAttribute('spellcheck', 'false');
        field.setAttribute('autocapitalize', 'off');

        this.inputHandler = function() {
            field.value = (field.value || '').replace(/\s+/g, ' ').trimStart();
        };

        field.addEventListener('input', this.inputHandler);
    };

    MathFieldWidget.prototype.destroy = function() {
        if (this.inputHandler) {
            this.fieldEl.removeEventListener('input', this.inputHandler);
        }
    };

    return MathFieldWidget;
});
